            assert(reverted);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(bytes32 hash, uint256 amount, bool occupy) public payable {
        require(address(this).balance >= amount + (occupy ? 1 ether : 0), "insufficient test balance");

        // Optionally occupy the guess slot through the public entry so the second call must revert.
        c.lockInGuess{value: occupy ? 1 ether : amount}(hash);

        // Before the deciding call, the slot is occupied exactly when `occupy` is true.
        // The deciding call must revert iff occupied or the sent value is not exactly 1 ether.
        bool reverted;
        try c.lockInGuess{value: amount}(hash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == (occupy || amount != 1 ether));
    }

    receive() external payable {}
}

